const tz = 'Asia/Karachi';
const today = DateTime.now().setZone(tz).startOf('day');
const rank = { P1: 1, P2: 2, P3: 3, P4: 4 };
const dot = { P1: '🔴', P2: '🟠', P3: '🟡', P4: '⚪' };
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fixTime = (t) => {
  t = String(t ?? '').trim();
  if (!t) return '';
  const p = t.split(':');
  return (p[0].length === 1 ? '0' : '') + p[0] + ':' + String(p[1] || '00').slice(0, 2);
};

const rows = $input.all().map((i) => i.json).filter((r) => r.taskId && ['Pending', 'Awaiting confirm'].includes(String(r.status ?? '').trim()));
const buckets = { today: [], tomorrow: [], parson: [] };

for (const r of rows) {
  const d = DateTime.fromISO(String(r.dueDate ?? '').trim(), { zone: tz }).startOf('day');
  if (!d.isValid) continue;
  const diff = Math.round(d.diff(today, 'days').days);
  const key = diff <= 0 ? 'today' : diff === 1 ? 'tomorrow' : diff === 2 ? 'parson' : null;
  if (!key) continue;
  const cat = String(r.category || r.aiSuggested || '').trim();
  buckets[key].push({ cat, task: r.task, time: fixTime(r.time), date: d, awaiting: String(r.status).trim() === 'Awaiting confirm' });
}

const sortFn = (a, b) => (rank[a.cat] || 5) - (rank[b.cat] || 5) || (a.time || '99:99').localeCompare(b.time || '99:99');
const line = (x, showDate) => (dot[x.cat] || '❔') + ' <b>' + (x.cat || '?') + '</b> ' + esc(x.task) + (x.time ? ' – ' + x.time : '') + (showDate ? ' (' + x.date.toFormat('d LLL') + ')' : '') + (x.awaiting ? ' <i>(category not confirmed)</i>' : '');

const sections = [
  ['today', '📌 <b>Today</b>', false],
  ['tomorrow', '📅 <b>Tomorrow</b> – ' + today.plus({ days: 1 }).toFormat('ccc d LLL'), false],
  ['parson', '🗓️ <b>Day after tomorrow</b> – ' + today.plus({ days: 2 }).toFormat('ccc d LLL'), false]
];

const focus = [...buckets.today];
const p1 = focus.filter((x) => x.cat === 'P1').length;
const p2 = focus.filter((x) => x.cat === 'P2').length;

let msg = '🌅 <b>Good morning!</b> ' + today.toFormat('cccc, d LLL yyyy') + '\n';
const total = buckets.today.length + buckets.tomorrow.length + buckets.parson.length;

if (total === 0) {
  msg += '\n✅ No pending tasks for today, tomorrow or the day after. Enjoy your day! 🎉';
} else {
  msg += 'Today\'s focus: <b>' + p1 + ' P1</b>, <b>' + p2 + ' P2</b>' + '\n';
  for (const [key, title, showDate] of sections) {
    const list = buckets[key].sort(sortFn);
    if (!list.length) continue;
    msg += '\n' + title + '\n' + list.map((x) => line(x, showDate)).join('\n') + '\n';
  }
  const first = [...buckets.today].sort(sortFn)[0];
  if (first) msg += '\n👉 Start with: <b>' + esc(first.task) + '</b>';
}

msg += '\n\nTo add a new task, just send me a message or a voice note.';
return [{ json: { message: msg } }];
